class Solution {
  public int[] timeTaken(int[][] edges) {
    int n = edges.length + 1;
    List<Integer>[] graph = new List[n];
    for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
    for (int[] e : edges) {
      graph[e[0]].add(e[1]);
      graph[e[1]].add(e[0]);
    }
    int[] parent = new int[n], order = new int[n], down = new int[n], up = new int[n];
    Arrays.fill(parent, -1);
    int size = 0;
    order[size++] = 0;
    for (int i = 0; i < size; i++) {
      for (int v : graph[order[i]]) {
        if (v != parent[order[i]]) {
          parent[v] = order[i];
          order[size++] = v;
        }
      }
    }
    // down[u]: time to mark everything below u once u is marked
    for (int i = n - 1; i >= 0; i--) {
      int u = order[i];
      for (int v : graph[u]) if (v != parent[u]) down[u] = Math.max(down[u], down[v] + cost(v));
    }
    int[] answer = new int[n];
    for (int u : order) {
      answer[u] = Math.max(down[u], up[u]);
      int best1 = 0, best2 = 0, who = -1;
      for (int v : graph[u]) {
        if (v == parent[u]) continue;
        int value = down[v] + cost(v);
        if (value > best1) {
          best2 = best1;
          best1 = value;
          who = v;
        } else if (value > best2) best2 = value;
      }
      for (int v : graph[u]) {
        if (v == parent[u]) continue;
        // up[v]: time to mark everything outside v's subtree once v is marked
        int sibling = Math.max(up[u], v == who ? best2 : best1);
        up[v] = sibling + cost(u);
      }
    }
    return answer;
  }

  // an odd node is marked one step after a marked neighbour, an even node two steps after
  private int cost(int node) {
    return node % 2 == 1 ? 1 : 2;
  }
}
